import target
import pytest

from target import split_heating_fee


def test_shares_sum_to_total():
    assert sum(split_heating_fee(1000, [28, 31])) == 1000


def test_february_weighted_by_actual_days():
    assert split_heating_fee(590, [28, 31]) == [280, 310]


def test_invalid_days_raise():
    with pytest.raises(ValueError):
        split_heating_fee(100, [0])
